import os
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest, DocumentAnalysisFeature

class DocumentClient:
    def __init__(self):
        self.client = DocumentIntelligenceClient(endpoint=os.getenv('AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT'), credential=os.getenv('AZURE_DOCUMENT_INTELLIGENCE_KEY'))

    def analyze_document(self, image_path):
        with open(image_path, "rb") as image_file:
            poller = self.client.begin_analyze_document('prebuilt-document', AnalyzeDocumentRequest(document=image_file))
            return poller.result()

from typing import List, Tuple

class DocumentModels:
    @staticmethod
    def normalize_text(text: str) -> str:
        return text.strip()

    @staticmethod
    def normalize_layout(layout: List[str]) -> List[str]:
        return [element.strip() for element in layout]

    @staticmethod
    def normalize_tables(tables: List[List[str]]) -> List[List[str]]:
        return [[cell.strip() for cell in row] for row in tables]

    @staticmethod
    def normalize_key_values(key_values: List[Tuple[str, str]]) -> List[Tuple[str, str]]:
        return [(key.strip(), value.strip()) for key, value in key_values]
